#!/system/bin/sh
# v2.6.5: 需同时更新 kctrl 二进制 + script_daemon
MOD="/data/adb/modules/kctrl"
echo "=== patch v2.6.5 ==="
if strings "$MOD/kctrl" 2>/dev/null | grep -q "v2.6.5"; then
  echo "kctrl: already v2.6.5"
else
  echo "kctrl: NOT v2.6.5 - copy new kctrl binary to $MOD/kctrl first!"
  echo "  from PC: kctrl_release/kctrl/kctrl -> phone Download/kctrl"
  echo "  then: cp /sdcard/Download/kctrl $MOD/kctrl && chmod 755 $MOD/kctrl"
fi
base64 -d << 'B64EOF' > "$MOD/script_daemon.sh"

B64EOF
chmod 755 "$MOD/script_daemon.sh"
pkill -f script_daemon.sh 2>/dev/null
killall kctrl 2>/dev/null
sleep 0.5
rm -f /data/local/tmp/kctrl_exec.fifo /data/local/tmp/kctrl_exec.job /data/local/tmp/kctrl_daemon.pid
sh "$MOD/service.sh"
sleep 1
grep -q 'ver=2.6.5' "$MOD/script_daemon.sh" && echo "daemon: OK v2.6.5" || echo "daemon: FAIL"
strings "$MOD/kctrl" 2>/dev/null | grep "v2.6.5" || echo "kctrl: still old - side key will NOT work until kctrl updated"
grep script_daemon "$MOD/klog.log" | tail -1
